import{_ as r,o,c as n,a2 as t,E as s,C as l}from"./chunks/framework.ChTAMbUy.js";const f=JSON.parse('{"title":"Agent Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"development/agentops/agent_gateway.md","filePath":"versions/development/agentops/agent_gateway.md","lastUpdated":1787837970000}'),i={name:"development/agentops/agent_gateway.md"};function d(c,e,g,h,p,u){const a=l("ControlledFlowsDiagram");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="agent-gateway" tabindex="-1">Agent Gateway <a class="header-anchor" href="#agent-gateway" aria-label="Permalink to &quot;Agent Gateway&quot;">​</a></h1><p>Agent Gateway is the shared data plane for model, MCP, and agent traffic in prokube. It connects agent runtimes to configured models and workspace tools, and exposes selected services to other applications. prokube builds this layer on <a href="https://agentgateway.dev/" target="_blank" rel="noreferrer">agentgateway</a> and the Kubernetes Gateway API.</p><div class="info custom-block"><p class="custom-block-title">Upstream references</p><ul><li><a href="https://agentgateway.dev/docs/kubernetes/latest/about/overview/" target="_blank" rel="noreferrer">Agentgateway overview</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest/llm/about/" target="_blank" rel="noreferrer">LLM consumption</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest/mcp/about/" target="_blank" rel="noreferrer">MCP connectivity</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest/mcp/virtual/" target="_blank" rel="noreferrer">Virtual MCP</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest/integrations/web-uis/kagent/" target="_blank" rel="noreferrer">Kagent integration</a></li><li><a href="https://agentgateway.dev/docs/kubernetes/latest/observability/otel-stack/" target="_blank" rel="noreferrer">Agentgateway observability</a></li></ul></div><p>This page explains how prokube uses Agent Gateway for agent workloads. For public paths, API-key scopes, and client authentication, see <a href="./../platform/agent_gateway.html">Agent Gateway</a> in Foundation and <a href="./../platform/api_keys.html">API Keys</a>.</p><h2 id="controlled-agent-traffic" tabindex="-1">Controlled Agent Traffic <a class="header-anchor" href="#controlled-agent-traffic" aria-label="Permalink to &quot;Controlled Agent Traffic&quot;">​</a></h2>',5)),s(a),e[1]||(e[1]=t('<p>Agent Gateway provides common routing between the main parts of an agent workload:</p><ul><li><strong>Agent to model:</strong> a kagent Agent uses its selected Model Configuration to reach a self-hosted or administrator-managed model.</li><li><strong>Agent to tool:</strong> workspace MCP endpoints are federated behind Agent Gateway and exposed to kagent through a <code>RemoteMCPServer</code>.</li><li><strong>Agent to agent:</strong> kagent agents are reachable over Agent2Agent (A2A) routes.</li><li><strong>Application to service:</strong> internal applications and authenticated external clients can call models, MCP servers, agents, and sandbox APIs through stable workspace routes.</li></ul><p>prokube creates and maintains the required gateway backends, routes, workspace isolation policies, and kagent references when supported resources are created through pkui.</p><h2 id="model-access" tabindex="-1">Model Access <a class="header-anchor" href="#model-access" aria-label="Permalink to &quot;Model Access&quot;">​</a></h2><p>Every declarative agent references a kagent <code>ModelConfig</code>. How its traffic reaches the model depends on the configuration&#39;s origin:</p><table tabindex="0"><thead><tr><th>Model path</th><th>How it is connected</th></tr></thead><tbody><tr><td>Model deployed through <a href="./llm_serving.html">LLM Serving</a></td><td>prokube creates an OpenAI-compatible route to the in-cluster model.</td></tr><tr><td>Administrator-managed external model</td><td>The <code>ModelConfig</code> points to an internal Agent Gateway provider route. Provider credentials remain centrally managed, and access is granted per workspace and model.</td></tr><tr><td>User-created external <code>ModelConfig</code></td><td>The agent uses the provider credential stored in the workspace Secret and connects through that configuration. This path is not automatically routed through the centrally managed provider gateway.</td></tr></tbody></table><p>Workspace users select an available Model Configuration when creating an <a href="./agents.html">Agent</a>. Administrators manage centralized providers and workspace model grants under <a href="./../admin/external_models.html">External Models</a>.</p><h2 id="mcp-federation-and-tool-selection" tabindex="-1">MCP Federation and Tool Selection <a class="header-anchor" href="#mcp-federation-and-tool-selection" aria-label="Permalink to &quot;MCP Federation and Tool Selection&quot;">​</a></h2><p>prokube combines the MCP endpoints available in a workspace into a federated Agent Gateway backend. kagent discovers that backend through the workspace <code>RemoteMCPServer</code> named <code>gateway-mcp</code>. This gives agents one stable MCP connection even when the set of workspace MCP servers changes.</p><p>When configuring an Agent, you can either:</p><ul><li>select individual discovered tools, which stores their names in the Agent&#39;s <code>mcpServer.toolNames</code> field; or</li><li>attach the complete <code>RemoteMCPServer</code> without <code>toolNames</code>, which makes all current and future tools from that connection available to the Agent.</li></ul><p>Tool selection controls which tools kagent presents to that Agent. Do not treat it as an independent network-security boundary: prokube does not currently materialize a separate Agent Gateway authorization policy for each Agent and selected tool. Use workspace separation and narrowly scoped MCP servers when a capability requires stronger isolation.</p><p>See <a href="./agents.html">Agents</a> for the UI workflow and <a href="./mcp_servers.html">MCP Servers</a> for deploying and operating tool servers.</p><h2 id="agent-to-agent-routes" tabindex="-1">Agent-to-Agent Routes <a class="header-anchor" href="#agent-to-agent-routes" aria-label="Permalink to &quot;Agent-to-Agent Routes&quot;">​</a></h2><p>prokube creates an A2A route for each supported kagent Agent. Other workloads can use that route to invoke the Agent without depending on its backing Pod or Service address.</p><p>Workloads in the same workspace can use the internal route with their workload identity and do not need an API key. Calls from other workspace or cluster namespaces are denied. External clients use the public <code>/a2a/&lt;workspace&gt;/&lt;agent&gt;</code> path and an API key scoped to that Agent.</p><h2 id="external-clients" tabindex="-1">External Clients <a class="header-anchor" href="#external-clients" aria-label="Permalink to &quot;External Clients&quot;">​</a></h2><p>Agent Gateway also exposes workspace services to SDKs, automation, CI jobs, and agents outside the platform. Public routes are grouped by service type, including <code>/ai</code>, <code>/mcp</code>, <code>/a2a</code>, and <code>/sandbox</code>.</p><p>External access is configured through service-scoped API keys, not on this page. See <a href="./../platform/api_keys.html">API Keys</a> for creating, rotating, and restricting keys and <a href="./../platform/agent_gateway.html">Agent Gateway</a> for the public routing model.</p><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h2><p>Traffic routed through Agent Gateway provides a common collection point for request metrics, logs, and traces. The currently documented user-facing view is the <a href="./../platform/api_keys.html#usage-dashboard">API Key Usage Dashboard</a>, which covers requests authenticated with an API key and does not represent all internal agent traffic.</p><p>For workload logs, Kubernetes events, metrics, and currently available tracing workflows, see <a href="./../platform/observability.html">Observability</a>. The underlying agentgateway data plane supports OpenTelemetry-based metrics and tracing integrations.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./agents.html">Agents</a></li><li><a href="./mcp_servers.html">MCP Servers</a></li><li><a href="./llm_serving.html">LLM Serving</a></li><li><a href="./../platform/agent_gateway.html">Agent Gateway</a></li><li><a href="./../platform/api_keys.html">API Keys</a></li><li><a href="./../admin/external_models.html">External Models</a></li><li><a href="./../platform/observability.html">Observability</a></li></ul>',24))])}const b=r(i,[["render",d]]);export{f as __pageData,b as default};
